<?php
declare(strict_types=1);
require_once __DIR__.'/../../Services/authService.php';
try{$user=auth_user_from_cookie();}catch(Throwable $e){error_log($e->__toString());http_response_code(503);exit('Service indisponible.');}
if(!$user){header('Location: index.php?mode=login');exit;}
$currentPage='messages';$pageTitle='Messages';$q=db()->prepare('SELECT c.Id_conversations,(SELECT GROUP_CONCAT(CONCAT(u.first_name," ",u.name) SEPARATOR ", ") FROM lier peer JOIN Users u ON u.Id_users=peer.Id_users WHERE peer.Id_conversations=c.Id_conversations AND peer.Id_users<>:peer_user) participants,(SELECT m.content FROM Messages m WHERE m.Id_conversations=c.Id_conversations ORDER BY m.Id_messages DESC LIMIT 1) preview,(SELECT m.created_at FROM Messages m WHERE m.Id_conversations=c.Id_conversations ORDER BY m.Id_messages DESC LIMIT 1) last_message FROM Conversations c JOIN lier mine ON mine.Id_conversations=c.Id_conversations WHERE mine.Id_users=:user_id ORDER BY COALESCE(last_message,c.created_at) DESC');$q->execute(['peer_user'=>$user['Id_users'],'user_id'=>$user['Id_users']]);$conversations=$q->fetchAll();$conversation=(int)($_GET['conversation']??0);$activeConversation=null;foreach($conversations as $item){if((int)$item['Id_conversations']===$conversation){$activeConversation=$item;break;}}if(!$activeConversation&&$conversations&&!isset($_GET['conversation'])){$activeConversation=$conversations[0];$conversation=(int)$activeConversation['Id_conversations'];}if(!$activeConversation)$conversation=0;
require __DIR__.'/../components/header.php';require __DIR__.'/../components/navBar.php';
?>
<style>
.chat-shell{height:calc(100dvh - 160px);min-height:420px}.chat-list-panel{width:340px;flex:none}.chat-shell{display:flex}.chat-window-panel{flex:1}.chat-bubble{max-width:min(78%,620px);overflow-wrap:anywhere}.chat-bubble.mine{margin-left:auto;background:#d9f8e9;border-radius:18px 18px 4px 18px}.chat-bubble.theirs{margin-right:auto;background:white;border:1px solid #edf0ef;border-radius:18px 18px 18px 4px}.chat-date{font-size:10px;color:#94a3a0;text-align:right;margin-top:5px}@media(max-width:767px){.chat-shell{height:calc(100dvh - 140px);min-height:400px;margin:-1.25rem}.chat-list-panel{width:100%;border:0}.chat-window-panel{display:none}.chat-shell.chat-open .chat-list-panel{display:none}.chat-shell.chat-open .chat-window-panel{display:flex;width:100%}}
</style>
<section id="chatShell" class="chat-shell <?= $conversation?'chat-open':'' ?> overflow-hidden rounded-none md:rounded-2xl border-y md:border border-slate-200 bg-white shadow-sm">
 <?php require __DIR__.'/../components/chatList.php'; ?>
 <div class="flex min-w-0 flex-1 flex-col"><?php require __DIR__.'/../components/chatWindow.php'; ?><?php require __DIR__.'/../components/chatInput.php'; ?></div>
</section>
<script>
(()=>{const conversationId=<?= $conversation ?>,ownId=<?= (int)$user['Id_users'] ?>,box=document.getElementById('chatMessages'),form=document.getElementById('chatForm'),shell=document.getElementById('chatShell');let lastId=0,loading=false;
async function refreshChat(){if(!conversationId||!box||loading)return;loading=true;try{const response=await fetch('index.php?api=messages-list&conversation='+conversationId,{headers:{Accept:'application/json'}});const data=await response.json();if(!response.ok)throw Error(data.error||'Chargement impossible');const nearBottom=box.scrollHeight-box.scrollTop-box.clientHeight<100;for(const m of data.messages){const id=Number(m.Id_messages);if(id<=lastId)continue;lastId=Math.max(lastId,id);const row=document.createElement('article');row.className='chat-bubble '+(Number(m.Id_users)===ownId?'mine':'theirs')+' px-4 py-2.5 shadow-sm';const body=document.createElement('p');body.className='whitespace-pre-wrap text-sm leading-6 text-slate-800';body.textContent=m.content;const time=document.createElement('div');time.className='chat-date';const d=new Date(String(m.created_at).replace(' ','T'));time.textContent=(Number(m.Id_users)===ownId?'Moi · ':'')+(Number.isNaN(d.getTime())?'':d.toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'}));row.append(body,time);box.append(row)}if(nearBottom)box.scrollTop=box.scrollHeight}catch(error){console.error(error)}finally{loading=false}}
if(form){const input=form.elements.content;input.addEventListener('input',()=>{input.style.height='auto';input.style.height=Math.min(input.scrollHeight,128)+'px'});input.addEventListener('keydown',event=>{if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();form.requestSubmit()}});form.addEventListener('submit',async event=>{event.preventDefault();const button=form.querySelector('button[type="submit"],button:not([type])');if(!input.value.trim())return;button.disabled=true;try{const body=new FormData(form);body.append('conversation',conversationId);const response=await fetch('index.php?api=message-send',{method:'POST',body});const result=await response.json();if(!response.ok||!result.ok)throw Error(result.error||'Le message n’a pas pu être envoyé.');form.reset();input.style.height='auto';await refreshChat()}catch(error){alert(error.message)}finally{button.disabled=false;input.focus()}});refreshChat();setInterval(refreshChat,2500)}
document.getElementById('mobileChatBack')?.addEventListener('click',()=>shell.classList.remove('chat-open'));document.getElementById('chatSearch')?.addEventListener('input',event=>{const query=event.target.value.toLocaleLowerCase('fr');document.querySelectorAll('[data-chat-item]').forEach(item=>item.classList.toggle('hidden',!item.textContent.toLocaleLowerCase('fr').includes(query)))});if(window.lucide)lucide.createIcons()})();
</script>
